function readBinaryWatch(turnedOn) {
  if (turnedOn === 0) {
    return ['0:00'];
  }
  const times = [];
  let mask = (1 << turnedOn) - 1;
  while (mask < 1 << 10) {
    const hour = mask >> 6;
    const minute = mask & 63;
    if (hour < 12 && minute < 60) {
      times.push(hour + ':' + (minute < 10 ? '0' : '') + minute);
    }
    const lowest = mask & -mask;
    const ripple = mask + lowest;
    const changed = ripple ^ mask;
    mask = ripple | ((changed / lowest) >> 2);
  }
  return times;
}

