function readBinaryWatch(turnedOn) {
  // Choose which of the 10 lights are lit, one light at a time.
  const weights = [8, 4, 2, 1, 32, 16, 8, 4, 2, 1];
  const result = [];
  const pick = (index, left, hours, minutes) => {
    if (left === 0) {
      if (hours <= 11 && minutes <= 59) result.push(`${hours}:${String(minutes).padStart(2, '0')}`);
      return;
    }
    if (index === weights.length) return;
    if (index < 4) pick(index + 1, left - 1, hours + weights[index], minutes);
    else pick(index + 1, left - 1, hours, minutes + weights[index]);
    pick(index + 1, left, hours, minutes);
  };
  pick(0, turnedOn, 0, 0);
  return result;
}

